// Build card HTML - TMDB movie object in, a complete 1080x1350 document out,
// ready to POST to hcti.io.
//
// This is the n8n port of the Make CSStoImage template. All of Make's inline
// helpers (join/map/slice/if/formatDate/floor) become plain JS here, which is
// why the conditionals are readable instead of nested one-liners.

const esc = (v) =>
  String(v ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');

const releaseDate = (iso) => {
  if (!iso) return '';
  const d = new Date(iso);
  if (isNaN(d.getTime())) return '';
  return d.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
};

const runtime = (mins) => {
  if (!mins || mins <= 0) return '';
  return `${Math.floor(mins / 60)}h ${mins % 60}m`;
};

const buildHtml = (m) => {
  const genres = (m.genres ?? []).slice(0, 3).map((g) => `<div class='pill'>${esc(g.name)}</div>`).join('');
  const cast = (m.credits?.cast ?? []).slice(0, 3).map((c) => c.name).join(', ');

  // Only show a rating once enough people have voted - a 10/10 from four
  // voters is worse than no rating at all.
  const rating =
    (m.vote_count ?? 0) >= 50 && m.vote_average
      ? `<span class="star">&#9733;</span><span>${m.vote_average.toFixed(1)}/10</span><span class="dot">&middot;</span>`
      : '';

  const date = releaseDate(m.release_date);
  const time = runtime(m.runtime);
  const timePart = time ? `<span class="dot">&middot;</span><span>${time}</span>` : '';

  // Some films have no backdrop. Fall back to a gradient rather than a blank box.
  const art = m.backdrop_path
    // 'original' rather than w1280: at device_scale 2 the card is 2160px wide,
    // and a 1280px backdrop stretched over that is visibly soft.
    ? `background-image:url('https://image.tmdb.org/t/p/original${esc(m.backdrop_path)}')`
    : 'background-image:linear-gradient(135deg,#1c1c22 0%,#2a2a33 50%,#141418 100%)';

  return `<!doctype html><html><head><meta charset="utf-8"><style>
  *{margin:0;padding:0;box-sizing:border-box}
  html,body{width:1080px;height:1350px}
  body{background:#0B0B0D;font-family:"Helvetica Neue",Arial,sans-serif;
       color:#fff;position:relative;overflow:hidden}
  .art{position:absolute;inset:0 0 auto 0;height:1000px;
       ${art};background-size:cover;background-position:center}
  .fade{position:absolute;inset:0;
        background:linear-gradient(180deg,
          rgba(11,11,13,.62) 0%, rgba(11,11,13,.18) 22%,
          rgba(11,11,13,.05) 32%, rgba(11,11,13,.82) 55%, #0B0B0D 68%)}
  .body{position:absolute;left:76px;right:76px;bottom:88px}
  .pills{display:flex;gap:16px;margin-bottom:30px}
  .pill{border:3px solid #F5C518;color:#F5C518;border-radius:999px;
        padding:11px 26px;font-size:25px;font-weight:800;letter-spacing:.13em}
  .title{font-size:82px;font-weight:800;letter-spacing:-.025em;
         line-height:1.02;margin-bottom:26px}
  .meta{display:flex;align-items:center;gap:18px;font-size:31px;
        font-weight:700;margin-bottom:32px;color:#EDEDF0}
  .meta .star{color:#F5C518}
  .dot{color:#5A5A62;font-weight:400}
  .overview{font-size:30px;line-height:1.42;color:#A6A6AE;margin-bottom:36px;
            display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;
            overflow:hidden}
  .row{display:flex;align-items:flex-start;gap:22px;margin-bottom:24px;
       font-size:28px;line-height:1.32}
  .row:last-child{margin-bottom:0}
  .ico{flex:0 0 42px;width:42px;height:42px;margin-top:2px}
  .row .lbl{color:#A6A6AE}
  .row b{color:#fff;font-weight:700}
  .mark{position:absolute;right:76px;top:70px;color:#F5C518;
        font-size:34px;font-weight:800;letter-spacing:-.02em;text-align:right;
        text-shadow:0 2px 16px rgba(0,0,0,.75)}
  .mark span{display:block;font-size:20px;font-weight:700;
             letter-spacing:.14em;color:rgba(255,255,255,.78);margin-top:6px}
</style></head><body>
  <div class="art"></div><div class="fade"></div>
  <div class="body">
    <div class="pills">${genres}</div>
    <div class="title">${esc(m.title)}</div>
    <div class="meta">${rating}<span>${esc(date)}</span>${timePart}</div>
    <div class="overview">${esc(m.overview)}</div>
    <div class="row">
      <svg class="ico" viewBox="0 0 24 24" fill="none" stroke="#F5C518"
stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
        <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/>
        <circle cx="12" cy="7" r="4"/></svg>
      <div class="lbl">Starring <b>${esc(cast)}</b></div></div>
    <div class="row">
      <svg class="ico" viewBox="0 0 24 24" fill="none" stroke="#F5C518"
stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
        <polyline points="23 6 13.5 15.5 8.5 10.5 1 18"/>
        <polyline points="17 6 23 6 23 12"/></svg>
      <div class="lbl"><b>Trending this week</b></div></div>
  </div>
  <div class="mark">ReelMatch<span>SWIPE &middot; MATCH &middot; WATCH</span></div>
</body></html>`;
};

// n8n entry point. Guarded so this file can also be require()d by preview-card.js.
if (typeof $input !== 'undefined') {
  return $input.all().map((item) => {
    const m = item.json;
    if (!m?.title) {
      throw new Error(`No TMDB movie data on item - got keys: ${Object.keys(m ?? {}).join(', ')}`);
    }
    return { json: { tmdb_id: m.id, title: m.title, html: buildHtml(m) } };
  });
}

// One item out per card: the hosted image URL, plus the facts the caption
// writer needs. The model does not know films released after its training
// cutoff, so it must be given the synopsis rather than asked to recall it.
return $input.all().map((item, i) => {
  const url = item.json.url;
  if (!url) {
    throw new Error(`hcti.io returned no url: ${JSON.stringify(item.json).slice(0, 300)}`);
  }
  const m = $('TMDB: movie details').all()[i]?.json ?? {};
  return { json: {
    image_url: url,
    tmdb_id: m.id,
    title: m.title,
    overview: m.overview ?? '',
    release_date: m.release_date ?? '',
    runtime: m.runtime ?? null,
    genres: (m.genres ?? []).map((g) => g.name).join(', '),
    cast: (m.credits?.cast ?? []).slice(0, 4).map((c) => c.name).join(', '),
  } };
});
